[CmdletBinding()]
param()
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'OrchestrationTaskKernel.ps1')
. (Join-Path $PSScriptRoot 'OrchestrationObservationVirtualization.ps1')
$passed=0; $failed=0
function Check([bool]$ok,[string]$name) { if($ok){$script:passed++;Write-Host "[PASS] $name"}else{$script:failed++;Write-Host "[FAIL] $name"} }
function Invoke-Case([string]$name,[scriptblock]$body) { try { & $body } catch { Check $false ($name+' exception: '+$_.Exception.ToString()) } }
$repo=Get-TaskKernelRepoRoot -RepoRoot ''
$root=Join-Path $repo ('cache\evidence-test-'+[guid]::NewGuid().ToString('N'))
$tasks=Join-Path $root 'tasks'; $store=Join-Path $root 'artifacts'; $flags=Join-Path $root 'flags.json'
$outsideFile=''
New-Item -ItemType Directory -Path $tasks -Force|Out-Null
$fixtureGit=Join-Path $root '.git'; New-Item -ItemType Directory -Path $fixtureGit -Force|Out-Null; $fixtureConfig=Join-Path $fixtureGit 'config'; [IO.File]::WriteAllText($fixtureConfig,'fixture')
[IO.File]::WriteAllText($flags,'{"task_kernel":{"enabled":true,"shadow":false}}',[Text.Encoding]::UTF8)
function New-TestTask([string]$id) { New-OrchestrationTask -TaskId $id -Objective 'test' -TaskType 'implementation' -Risk 'low' -Actor 'planner' -RuntimeId 'opencode-v1' -RuntimeGeneration 1 -RuntimeProfile 'v1' -RuntimeVersion '1.0' -ReadScopes @('src') -WriteScopes @('src') -Grants @('fs.read','fs.write') -AcceptanceCriteria @('works') -ExpectedArtifacts @('src/file') -TasksDir $tasks -FlagsPath $flags -TelemetryRoot $root }
try {
Invoke-Case T1 { $id='detail-t1-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $content='a'*120000; $r=Set-OrchestrationTaskWorkerResult -TaskId $id -Status candidate_pass -ClaimedEvidence @('criterion:0') -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent $content -EvidenceStoreDir (Join-Path $store $id); $q=Get-OrchestrationTask -TaskId $id -TasksDir $tasks; $d=$q.worker_result.detail; Check ($r.ok -and $d.preview.Length -le 2000 -and $d.truncated -and $d.total_chars -eq 120000 -and $d.artifact_ref.sha256 -match '^[0-9a-f]{64}$' -and (Get-Item $d.artifact_ref.path).Length -ge 120000) 'T1 bounded preview/hash/artifact' }
Invoke-Case T2 { $id='detail-t2-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $c='b'*120001; $r=Set-OrchestrationTaskWorkerResult -TaskId $id -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent $c -EvidenceStoreDir (Join-Path $store $id); $ref=(Get-OrchestrationTask -TaskId $id -TasksDir $tasks).worker_result.detail.artifact_ref; $good=Read-OrchestrationArtifactRef -Path $ref.path -ExpectedSha256 $ref.sha256 -StoreDir (Join-Path $store $id); [IO.File]::WriteAllText($ref.path,'tamper'); $bad=Read-OrchestrationArtifactRef -Path $ref.path -ExpectedSha256 $ref.sha256 -StoreDir (Join-Path $store $id); Check ($r.ok -and $good.ok -and $good.content -ceq $c -and $bad.error -ceq 'ARTIFACT_HASH_MISMATCH') 'T2 recall and tamper detection' }
Invoke-Case T3 { $id='detail-t3-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $r=Set-OrchestrationTaskWorkerResult -TaskId $id -Status candidate_pass -ClaimedEvidence @('criterion:0') -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent ('c'*120002) -EvidenceStoreDir (Join-Path $store $id); $q=Get-OrchestrationTask -TaskId $id -TasksDir $tasks; $wr=$q.worker_result; Check ($r.ok -and $wr.claimed_evidence[0] -ceq 'criterion:0' -and $wr.revision -eq 2 -and $wr.status -ceq 'candidate_pass' -and $wr.produced_by -ceq 'coder' -and $q.schema_version -eq 1 -and -not $q.Contains('evidence_refs')) 'T3 record contract unchanged' }
Invoke-Case T3-DetailPath-positive-boundaries { $id='detail-path-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $dir=Join-Path $root 'cache'; New-Item -ItemType Directory -Path $dir -Force|Out-Null; $file=Join-Path $dir 'path-detail.txt'; [IO.File]::WriteAllText($file,'legitimate detail'); $good=Set-OrchestrationTaskWorkerResult -TaskId $id -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $file -EvidenceStoreDir (Join-Path $root 'cache\artifacts'); $record=Get-OrchestrationTask -TaskId $id -TasksDir $tasks; $ref=$record.worker_result.detail.artifact_ref; $keys=@($ref.Keys); $sameKeys=($keys.Count -eq 5 -and (@($keys|Sort-Object) -join ',') -ceq 'bytes,created,kind,path,sha256'); $id2='detail-boundary-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id2; $upper=$file.Replace('\cache\','\CACHE\'); $upperResult=Set-OrchestrationTaskWorkerResult -TaskId $id2 -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $upper -EvidenceStoreDir (Join-Path $root 'cache\upper-artifacts'); $idRel='detail-relative-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $idRel; $relative=$file.Substring($repo.Length).TrimStart('\','/'); $relativeResult=Set-OrchestrationTaskWorkerResult -TaskId $idRel -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $relative -EvidenceStoreDir (Join-Path $root 'cache\relative-artifacts'); $id3='detail-boundary-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id3; $attempts=@(); foreach($p in @((Join-Path $repo 'cachefoo\x.txt'),(Join-Path $repo 'cache\..\README.md'), '\\server\share\detail.txt', '\\?\C:\cache\detail.txt')){$attempts+=Set-OrchestrationTaskWorkerResult -TaskId $id3 -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $p}; $storeBad=Set-OrchestrationTaskWorkerResult -TaskId $id3 -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent 'outside-cache' -EvidenceStoreDir (Join-Path $repo 'cachefoo-store'); Check ($good.ok -and $record.worker_result.detail -and $sameKeys -and $upperResult.ok -and $relativeResult.ok -and $storeBad.error -ceq 'DETAIL_ARTIFACT_FAILED' -and @($attempts|Where-Object{$_.error -ceq 'DETAIL_PATH_NOT_ALLOWED'}).Count -eq 4) 'T3 DetailPath allowed rooted/relative/case-insensitive; rejects boundary, traversal, UNC and device paths; store confined' }
Invoke-Case T4 { $id='detail-t4-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $r=Set-OrchestrationTaskWorkerResult -TaskId $id -Status blocked -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent 'sk-SYNTHETICSECRET' -EvidenceStoreDir (Join-Path $store $id); $d=(Get-OrchestrationTask -TaskId $id -TasksDir $tasks).worker_result.detail; $a=Read-OrchestrationArtifactRef -Path $d.artifact_ref.path -ExpectedSha256 $d.artifact_ref.sha256 -StoreDir (Join-Path $store $id); Check ($r.ok -and $d.preview -match '\[REDACTED\]' -and $d.preview -notmatch 'sk-SYNTHETICSECRET' -and $a.content -match '\[REDACTED\]' -and $a.content -notmatch 'sk-SYNTHETICSECRET') 'T4 redaction in preview and artifact' }
Invoke-Case T5 { $id='detail-t5-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $f=Join-Path $tasks ($id+'.json'); $initial=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); $conf=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent x -DetailPath README.md; $out=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent x -EvidenceStoreDir (Join-Path $env:TEMP ([guid]::NewGuid().ToString('N'))); $script:outsideFile=Join-Path $env:TEMP ('evo12-outside-'+[guid]::NewGuid().ToString('N')+'.txt'); [IO.File]::WriteAllText($script:outsideFile,'outside'); $outside=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $script:outsideFile; $git=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $fixtureConfig; $after=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); Check ($conf.error -ceq 'DETAIL_INPUT_CONFLICT' -and $out.error -ceq 'DETAIL_ARTIFACT_FAILED' -and $outside.error -ceq 'DETAIL_PATH_NOT_ALLOWED' -and $git.error -ceq 'DETAIL_PATH_NOT_ALLOWED' -and $initial -ceq $after) 'T5 refusals preserve identical record bytes' }
Invoke-Case T5-sensitive-paths { $id='detail-t5p-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $f=Join-Path $tasks ($id+'.json'); $initial=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); $base=Join-Path $root 'cache'; New-Item -ItemType Directory -Path $base -Force|Out-Null; $models=Join-Path $base 'models.jsonc'; [IO.File]::WriteAllText($models,'{}'); $taskJson=Join-Path $tasks ($id+'.json'); $colon=Join-Path $base 'bad:segment.txt'; $tilde=Join-Path $base 'GIT~1'; [IO.File]::WriteAllText($tilde,'x'); $envFile=Join-Path $base '.env.local'; [IO.File]::WriteAllText($envFile,'x'); $paths=@($fixtureConfig,$models,($models+'::$DATA'),$taskJson,$colon,$tilde,$envFile); $results=@(); foreach($p in $paths){$results+=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $p}; $final=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); if (@($results|Where-Object{$_.error -ceq 'DETAIL_PATH_NOT_ALLOWED'}).Count -ne 7 -or $initial -cne $final) { Write-Host ('[T5SENSITIVE] '+(($results|ForEach-Object{$_.error}) -join ',')+' bytesSame='+($initial -ceq $final)) }; Check (@($results|Where-Object{$_.error -ceq 'DETAIL_PATH_NOT_ALLOWED'}).Count -eq 7 -and $initial -ceq $final) 'T5 .git/models/ADS/TasksDir/colon/tilde/env denied without write' }
Invoke-Case T5-size-empty { $id='detail-t5s-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $f=Join-Path $tasks ($id+'.json'); $initial=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); $p=Join-Path (Join-Path $root 'cache') ('large-'+$id); [IO.File]::WriteAllBytes($p,(New-Object byte[] (1048577))); $large=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath $p; $empty=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath ' '; $final=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); Check ($large.error -ceq 'DETAIL_TOO_LARGE' -and $empty.error -ceq 'DETAIL_PATH_INVALID' -and $initial -ceq $final) 'T5 oversized and empty DetailPath typed without write' }
Invoke-Case T5-junction { $id='detail-t5j-'+[guid]::NewGuid().ToString('N').Substring(0,8); $null=New-TestTask $id; $junction=Join-Path (Join-Path $root 'cache') ('junction-'+[guid]::NewGuid().ToString('N')); $target=Join-Path $env:TEMP ('evo12-target-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $target -Force|Out-Null; [IO.File]::WriteAllText((Join-Path $target 'data.txt'),'external'); try { New-Item -ItemType Junction -Path $junction -Target $target -ErrorAction Stop|Out-Null } catch { Write-Host ('[SKIP] T5 junction: '+$_.Exception.Message); Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction SilentlyContinue; return }; try { $f=Join-Path $tasks ($id+'.json'); $before=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); $jPath=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailPath (Join-Path $junction 'data.txt'); $jStore=Set-OrchestrationTaskWorkerResult -TaskId $id -Status failed -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent 'junction-store' -EvidenceStoreDir (Join-Path $junction 'artifacts'); $after=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f)); Check ($jPath.error -ceq 'DETAIL_PATH_NOT_ALLOWED' -and $jStore.error -ceq 'DETAIL_ARTIFACT_FAILED' -and $before -ceq $after) 'T5 intermediate junction blocks paths without record writes' } finally { try { [IO.Directory]::Delete($junction) } catch { }; Remove-Item -LiteralPath $target -Recurse -Force -Confirm:$false -ErrorAction SilentlyContinue } }
Invoke-Case T6 { $id1='nodetail-'+[guid]::NewGuid().ToString('N').Substring(0,8); $id2='withdetail-'+[guid]::NewGuid().ToString('N').Substring(0,8); $ids=@($id1,$id2); foreach($id in $ids){$null=New-TestTask -id $id}; $a=Set-OrchestrationTaskWorkerResult -TaskId $ids[0] -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root; if(-not $a.ok){Check $false ('T6 without detail: '+$a.error); return}; $storeWatch=[Diagnostics.Stopwatch]::StartNew(); $b=Set-OrchestrationTaskWorkerResult -TaskId $ids[1] -Status candidate_pass -ClaimedEvidence @() -ProducedBy coder -ExpectedRevision 1 -TasksDir $tasks -FlagsPath $flags -RepoRoot $repo -TelemetryRoot $root -DetailContent ('z'*120003) -EvidenceStoreDir (Join-Path $store $ids[1]); $storeWatch.Stop(); if(-not $b.ok){Check $false ('T6 with detail: '+$b.error); return}; $plain=(Get-Item (Join-Path $tasks ($ids[0]+'.json'))).Length; $with=(Get-Item (Join-Path $tasks ($ids[1]+'.json'))).Length; $delta=$with-$plain; $d=(Get-OrchestrationTask -TaskId $ids[1] -TasksDir $tasks).worker_result.detail; $art=(Get-Item $d.artifact_ref.path).Length; $sw=[Diagnostics.Stopwatch]::StartNew(); $null=Read-OrchestrationArtifactRef -Path $d.artifact_ref.path -ExpectedSha256 $d.artifact_ref.sha256 -StoreDir (Join-Path $store $ids[1]); $sw.Stop(); Write-Host ("[MEASURE]json_without_detail={0} json_with_detail={1} delta={2} artifact_bytes={3} store_ms={4} recall_ms={5}" -f $plain,$with,$delta,$art,$storeWatch.ElapsedMilliseconds,$sw.ElapsedMilliseconds); Check ($with -lt 10000 -and $delta -gt 0 -and $delta -lt 10000 -and $art -ge 120000 -and $with -lt ($art/10)) 'T6 JSON bounded against full artifact' }
} finally { if (-not [string]::IsNullOrWhiteSpace($outsideFile)) { Remove-Item -LiteralPath $outsideFile -Force -ErrorAction SilentlyContinue }; Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue }
Write-Host ("RESULTS {0} PASS, {1} FAIL" -f $passed,$failed); if($failed){exit 1}
